"use strict";
window.DeckCommerce=(()=>{
  const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
  const t=(s,p)=>DeckI18n.t(s,p);
  function money(cents){if(!Number.isSafeInteger(cents)||cents<0)return "";return "US$ "+new Intl.NumberFormat(DeckI18n.intlLocale,{minimumFractionDigits:cents%100?2:0,maximumFractionDigits:2}).format(cents/100);}
  function stamp(p){return p?`<div class="skill-valuation"><span>${esc(t("Preço proposto"))}<strong>${esc(money(p.priceCents))}</strong></span><span class="demo-price">${esc(t("Grátis na demo"))}</span></div>`:"";}
  function assessment(s){const p=s.pricing;if(!p)return "";return `<section class="pricing-assessment"><h3>${esc(t("Como avaliamos esta skill"))}</h3>${stamp(p)}<p>${esc(p.reason)}</p><p>${esc(t("Complexidade do escopo"))}: <strong>${esc(p.complexityLabel)}</strong></p><dl class="pricing-dimensions">${p.dimensions.map(d=>`<div><dt>${esc(d.label)}</dt><dd><meter min="1" max="5" value="${d.score}" aria-label="${esc(d.label)}">${d.score}/5</meter><span>${d.score}/5</span></dd></div>`).join("")}</dl><p class="fine">${esc(t("Notas de 1 a 5. Esforço de conferência não significa teste já concluído."))}</p><p>${esc(p.basis)}</p>${p.variantNote?`<p>${esc(p.variantNote)}</p>`:""}<p class="fine">${esc(p.notice)} ${esc(t("Ferramentas, assinaturas externas e serviços de implantação não estão incluídos."))}</p></section>`;}
  function bundlePrice(p){if(!p)return "";return `<div class="bundle-price"><span>${esc(t("Combo proposto"))}</span><strong>${esc(money(p.priceCents))}</strong> <span class="bundle-discount">${esc(t("{percent}% de desconto proposto",{percent:p.discountPercent}))}</span><small>${esc(t("Soma das skills: {amount}",{amount:money(p.individualTotalCents)}))} · ${esc(t("Economia proposta: {amount}",{amount:money(p.savingsCents)}))}</small><p>${esc(t("Grátis na demo"))}</p></div>`;}
  function combo(c,skills){return `<article class="combo-tile"><h3>${esc(c.title)}</h3><p>${esc(c.purpose)}</p><ul>${c.skillIds.map(id=>{const s=skills.find(s=>s.id===id);return `<li><button class="text-button" data-open="${esc(id)}"><span>${esc(s?.code)}</span> ${esc(s?.title)}</button></li>`}).join("")}</ul>${bundlePrice(c)}<div class="combo-actions"><button class="btn secondary" data-view-combo="${esc(c.id)}">${esc(t("Ver as cartas"))}</button><button class="text-button" data-save-combo="${esc(c.id)}">${esc(t("Salvar combo no Meu Deck"))}</button></div></article>`;}
  function power(s){const g=s.game;if(!g)return "";return `<section class="power-arena" style="--power-hue:${DeckArt.hue(s)}"><div class="power-sigil" aria-hidden="true">${String(g.level).padStart(2,"0")}</div><p class="power-school">${esc(g.school)} · ${esc(t("Nível de coleção {level}",{level:g.level}))}</p><h3>${esc(s.universe.alias)}</h3><p class="power-flavor">${esc(g.flavor)}</p><div class="power-meters"><div><span>${esc(t("Ataque criativo"))}</span><strong>${esc(t("ATQ"))} / ${g.attack}</strong><meter min="0" max="4000" value="${g.attack}" aria-label="${esc(t("Ataque criativo"))}">${g.attack}</meter></div><div><span>${esc(t("Defesa estratégica"))}</span><strong>${esc(t("DEF"))} / ${g.defense}</strong><meter min="0" max="4000" value="${g.defense}" aria-label="${esc(t("Defesa estratégica"))}">${g.defense}</meter></div></div><div class="power-technique"><h4>${esc(t("Técnica especial"))}</h4><p>${esc(s.universe.tagline)}</p><p>${esc(s.universe.purpose)}</p></div><div class="power-actions"><button class="btn power-summon" data-summon="${esc(s.id)}">✦ ${esc(t("Invocar carta"))}</button><button class="text-button" data-detail-tab="example">${esc(t("Levar para a missão"))} ↗</button></div><p class="fine">${esc(t("O efeito é visual e sonoro; não executa a skill."))}</p><p class="power-boundary">${esc(g.notice)}</p><p class="power-announcement" role="status" aria-live="polite"></p></section>`;}
  return {money,stamp,assessment,bundlePrice,combo,power};
})();
